pub(crate) async fn task_comment_async(
    repo: &Path,
    wave: Option<&str>,
    issue: &str,
    message: Option<&str>,
    steer: bool,
) -> OpsResult<TaskComments> {
    let (store, task) = resolve_saved_task(repo, wave, issue).await?;
    if let Some(message) = message {
        append_task_comment(&store, &task, message, steer)?;
        let owner = store
            .get_wave(&task.wave_id)
            .await
            .map_err(|error| OpsError::Message(error.to_string()))?
            .ok_or_else(|| OpsError::Message("Task Wave is missing".into()))?;
        super::planning_sync::sync_after_save(&store, owner.repo()).await;
    }
    let refresh_error = if message.is_none() && task.linear_id.is_some() {
        match tokio::time::timeout(
            std::time::Duration::from_secs(5),
            super::linear_observe::refresh_task_comments(&store, &task),
        )
        .await
        {
            Ok(Ok(())) => None,
            Ok(Err(error)) => Some(error.to_string()),
            Err(_) => Some("Comment refresh timed out; showing saved comments".into()),
        }
    } else {
        None
    };
    let mut thread = store
        .sqlite
        .task_comments(&task.id)
        .map_err(|error| OpsError::Message(error.to_string()))?;
    thread.refresh_error = refresh_error;
    Ok(thread)
}

pub(crate) async fn sync_after_save(store: &Store, repo: &str) {
    let attempt = async {
        let config = crate::config::load_config(Some(Path::new(repo)))
            .map_err(message)?
            .unwrap_or_default();
        match config.planning_transport() {
            crate::config::PlanningConfig::Git { .. } => publish_repository(store, repo).await,
            crate::config::PlanningConfig::Linear {} => {
                tokio::time::timeout(std::time::Duration::from_secs(5), async {
                    super::planning_export::sync_repository_exports(store, repo).await?;
                    let (fields, comments, state) = tokio::join!(
                        super::planning_delivery::sync_repository_fields(store, repo),
                        super::linear_observe::sync_repository_deliveries(store, repo, false),
                        super::linear_observe::sync_repository_deliveries(store, repo, true)
                    );
                    fields?;
                    comments?;
                    state?;
                    Ok(())
                })
                .await
                .map_err(message)?
            }
        }
    };
    if let Err(error) = attempt.await {
        tracing::debug!(%error, "planning synchronization pending after local save");
        eprintln!("Saved locally; planning synchronization pending. See `lf planning status`.");
    }
}

fn write_comment(conn: &Connection, task: &TaskId, comment: &TaskComment) -> StoreResult<()> {
    planning_write::create(
        conn,
        "",
        &crate::work::edit::WorkEdit::for_target(
            &comment.id,
            &[
                Edit::CommentTask(task.to_string()),
                Edit::CommentContent(crate::work::edit::CommentContent {
                    body: comment.body.clone(),
                    author: comment.author.clone(),
                    created_at: comment.created_at.clone(),
                }),
            ],
        ),
    )
}

// Local and acquired comments share the field writer; only local saves enqueue delivery.
fn insert_authored_comment(
    conn: &Connection,
    task: &TaskId,
    comment: &TaskComment,
) -> StoreResult<()> {
    write_comment(conn, task, comment)?;
    conn.execute(
        "INSERT INTO task_comment_deliveries(comment_id,comment_json) VALUES(?1,?2)",
        params![comment.id, serde_json::to_string(comment)?],
    )?;
    Ok(())
}

pub fn append_task_comment(&self, task: &TaskId, comment: &TaskComment) -> StoreResult<()> {
    let mut conn = self.conn.lock().expect("store mutex poisoned");
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let task = super::children::task_on(&tx, task)?.ok_or(StoreError::NotFound)?;
    super::children::require_task_not_deleted(&tx, &task)?;
    let created_at = comment.created_at.as_deref().ok_or_else(|| {
        StoreError::InvalidData("local comments require a creation time".into())
    })?;
    if comment.body.trim().is_empty() {
        return Err(StoreError::InvalidData(
            "Task comment cannot be empty".into(),
        ));
    }
    let author = serde_json::to_string(&comment.author)?;
    let previous: Option<(String, String, String, String)> = tx
        .query_row(
            "SELECT task_id,body,author,created_at FROM task_comments WHERE id=?1",
            [&comment.id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if let Some(previous) = previous {
        if previous
            != (
                task.id.to_string(),
                comment.body.clone(),
                author,
                created_at.to_string(),
            )
        {
            return Err(StoreError::InvalidData(
                "comment identity already belongs to another comment".into(),
            ));
        }
        return Ok(());
    }
    insert_authored_comment(&tx, &task.id, comment)?;
    if let TaskCommentAuthor::Person { name } = &comment.author {
        if crate::ops::linear_observe::is_direction_comment(&comment.body, Some("local")) {
            let text = match name {
                Some(name) => format!("Comment {} by {name}:\n\n{}", comment.id, comment.body),
                None => format!(
                    "Comment {} (attribution unresolved):\n\n{}",
                    comment.id, comment.body
                ),
            };
            Self::append_task_steer_in(&tx, &task.id, &crate::durable::Author::User, &text)?;
        }
    }
    tx.commit()?;
    Ok(())
}

pub(crate) fn write(
    conn: &Connection,
    edits: &[WorkEdit],
    origin: WriteOrigin,
) -> StoreResult<bool> {
    let mut changed = false;
    for ((table, id), values) in grouped(edits) {
        changed |= write_record(conn, table, id, &values, origin)?;
    }
    Ok(changed)
}

/// Save local Work in the caller's transaction, including its causal identity.
pub(crate) fn local(conn: &Connection, edits: &[WorkEdit]) -> StoreResult<bool> {
    write(conn, edits, WriteOrigin::Local)
}

/// Create shared records before attaching any machine-local execution data.
pub(crate) fn create(conn: &Connection, repo: &str, edits: &[WorkEdit]) -> StoreResult<()> {
    let records = grouped(edits);
    // Foreign-key parents exist before children even when the caller's edits
    // arrive in a different order. Capturing fields still uses the common writer.
    for table in WORK_TABLES {
        for (&(record_table, id), values) in &records {
            if record_table == table {
                ensure_record(conn, repo, table, id, values)?;
            }
        }
    }
    write(conn, edits, WriteOrigin::Local)?;
    Ok(())
}

